2	import './Header.css';
3	
4	/**
5	 * Header — app-level header bar.
6	 *
7	 * Shows the PC Pal title, user info (clickable to edit), and admin button.
8	 */
9	function Header({ user, onUpdateProfile, onSignOut, onAdminClick, showingAdmin }) {
10	  const [editing, setEditing] = useState(false);
11	  const [editName, setEditName] = useState('');
12	  const [editOs, setEditOs] = useState('');
13	  const [editComfort, setEditComfort] = useState(1);
14	  const [editModel, setEditModel] = useState('');
15	  const [editTrainingOptIn, setEditTrainingOptIn] = useState(false);
16	  const [availableModels, setAvailableModels] = useState([]);
17	  const [saving, setSaving] = useState(false);
18	  const [saveError, setSaveError] = useState('');
19	  const [showMemories, setShowMemories] = useState(false);
20	  const [memories, setMemories] = useState([]);
21	  const [loadingMemories, setLoadingMemories] = useState(false);
22	
23	  // Fetch available models when edit modal opens
24	  useEffect(() => {
25	    if (!editing) return;
26	    fetch('/api/models')
27	      .then(r => r.json())
28	      .then(data => setAvailableModels(data))
29	      .catch(() => setAvailableModels([]));
30	  }, [editing]);
31	
32	  const openEdit = () => {
33	    if (!user) return;
34	    setEditName(user.name || '');
35	    setEditOs(user.os_type || 'Windows');
36	    setEditComfort(user.comfort_level || 1);
37	    setEditModel(user.model_preference || '');
38	    setEditTrainingOptIn(Boolean(user.training_opt_in));
39	    setSaveError('');
40	    setEditing(true);
41	  };
42	
43	  const handleSave = async () => {
44	    if (!onUpdateProfile) {
45	      setSaveError('Profile update is unavailable right now.');
46	      return;
47	    }
48	    if (!editName.trim()) {
49	      setSaveError('Please enter your name.');
50	      return;
51	    }
52	    setSaveError('');
53	    setSaving(true);
54	    try {
55	      const result = await onUpdateProfile({
56	        name: editName.trim(),
57	        os_type: editOs,
58	        comfort_level: editComfort,
59	        model_preference: editModel || null,
60	        training_opt_in: editTrainingOptIn ? 1 : 0,
61	      });
62	      if (!result) {
63	        throw new Error('No profile was returned. Try reloading the page.');
64	      }
65	      setEditing(false);
66	    } catch (e) {
67	      console.error('Failed to update profile:', e);
68	      setSaveError(e?.message || 'Could not save your profile. Please try again.');
