const STORAGE_KEY = 'pcpal:a11y-prefs';

const DEFAULTS = {
  textSize: 'normal',     // 'normal' | 'large' | 'xlarge'
  highContrast: false,
  readAloud: false,
};

function loadPrefs() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return DEFAULTS;
    const parsed = JSON.parse(raw);
    return { ...DEFAULTS, ...parsed };
  } catch {
    return DEFAULTS;
  }
