        const pending = pendingCommands.get(msg.requestId);
        if (pending) {
          clearTimeout(pending.timer);
          pendingCommands.delete(msg.requestId);
          pending.resolve({ imageBase64: msg.imageBase64, error: msg.error, message: msg.message });
        }

