        console.log(`[relay] Agent registered with code: ${agentCode}`);
        setTimeout(() => {
          if (pendingAgents.has(agentCode)) {
            pendingAgents.delete(agentCode);
            console.log(`[relay] Pairing code ${agentCode} expired`);
          }
