  if (!lastMsg || lastMsg.role !== 'assistant' || !lastMsg.text) return;
  if (lastSpokenIdRef.current === lastMsg.id) return;
  lastSpokenIdRef.current = lastMsg.id;
  speech.speak(lastMsg.text);
}, [messages, readAloud, isViewingPast, speech]);

