    <div className={`chat-layout ${showSidePanel ? 'chat-layout--split' : ''} ${showTerminal ? 'chat-layout--terminal' : ''}`}>
    <div className="chat-window">
      <div className="chat-header">
        <ConnectComputer isConnected={agentConnected} onPair={pairAgent} />
        <button
          className={`chat-header__screen-share-btn ${screenSharing ? 'chat-header__screen-share-btn--active' : ''}`}
          onClick={() => setScreenSharing(prev => !prev)}
          title={screenSharing ? 'Stop sharing your screen' : 'Share your screen so PC Pal can see and help'}
        >
          {screenSharing ? 'Stop Sharing' : 'Share Screen'}
        </button>
        {!isViewingPast && (
          <button
            type="button"
            className={`chat-header__terminal-btn ${terminalOpen && agentConnected ? 'chat-header__terminal-btn--active' : ''}`}
            onClick={() => setTerminalOpen(prev => !prev)}
            aria-label={
              !agentConnected
                ? 'Connect your computer to use the terminal'
                : terminalOpen ? 'Close terminal' : 'Open terminal'
            }
            title={!agentConnected ? 'Connect your computer to use the terminal' : undefined}
            disabled={!agentConnected}
          >
            Terminal
          </button>
        )}
        <button
          type="button"
          className="chat-header__end-btn"
          onClick={endChat}
          disabled={!hasUserMessage || !!feedbackPrompt}
          aria-label="End chat and leave feedback"
        >
          End chat
        </button>
