        .filter(a => !dismissedMsgIds.has(a.msgId) || a.msgId === msgId)
        .findIndex(a => a.msgId === msgId);
      setActiveArtifactIdx(visibleIdx >= 0 ? visibleIdx : 0);
    }
  };

