  const handleMoveToSide = (msgId) => {
    // Un-dismiss if it was dismissed
    setDismissedMsgIds(prev => {
      const next = new Set(prev);
      next.delete(msgId);
      return next;
    });
    setInlineMsgIds(prev => {
      const next = new Set(prev);
      next.delete(msgId);
      return next;
    });
