          <div className="chat-empty">
            <p className="chat-empty__text">
              {isViewingPast
                ? 'This conversation has no messages.'
                : <>Hello! I&apos;m PC Pal, your friendly tech helper.<br />Ask me anything about your computer!</>
              }
            </p>
          </div>
        )}

