          <MessageBubble
            key={msg.id}
            message={msg}
            onRunCommand={runCommand}
            inlineMode={inlineMsgIds.has(msg.id)}
            onMoveToSide={() => handleMoveToSide(msg.id)}
            onClickArtifact={() => navigateToArtifact(msg.id)}
