        <div className="chat-readonly-banner">
          This is a past conversation.
        </div>
      ) : (
        <>
          <StepSequencePanel activeSequence={activeSequence} onSendMessage={sendMessage} />
          {screenSharing && (
            <ScreenShare
              onScreenFrame={sendScreenFrame}
              onStop={() => setScreenSharing(false)}
            />
          )}
          <MessageInput onSend={sendMessage} onGatherResources={gatherResources} isTyping={isTyping} />
        </>
      )}

