          onNavigate={setActiveArtifactIdx}
          onClose={() => handleDismiss(currentArtifact.msgId)}
          onMoveToInline={() => handleMoveToInline(currentArtifact.msgId)}
          onRunCommand={runCommand}
          onSendMessage={sendMessage}
        />
      )
    )}
    </div>
  );
}

