function ChatWindow({ userId, userName, readAloud, viewingConversationId, onConversationChange, startNewChatRef }) {
  const {
    messages: liveMessages,
    sendMessage,
    gatherResources,
    pairAgent,
    agentConnected,
    runCommand,
    isConnected,
    isTyping,
    activeSequence,
    welcomeBack,
    dismissWelcomeBack,
    conversationId,
    feedbackPrompt,
    startNewChat,
    endChat,
    submitFeedback,
    skipFeedback,
    terminalHistory,
    terminalCwd,
    sendTerminalCommand,
    sendScreenFrame,
  } = useChat(userId);
  const [screenSharing, setScreenSharing] = useState(false);
  const bottomRef = useRef(null);
  const speech = useSpeech();
  const lastSpokenIdRef = useRef(null);

  // Expose startNewChat to parent via ref
  useEffect(() => {
    if (startNewChatRef) startNewChatRef.current = startNewChat;
  }, [startNewChat, startNewChatRef]);

  // Viewing a past conversation: fetch its messages
  const [pastMessages, setPastMessages] = useState([]);
  const [loadingPast, setLoadingPast] = useState(false);
  const isViewingPast = !!(viewingConversationId && viewingConversationId !== conversationId);

  useEffect(() => {
    if (!isViewingPast || !viewingConversationId) {
      // Clear past messages when not viewing — defer to avoid setState-in-effect lint
      queueMicrotask(() => setPastMessages([]));
      return;
    }
    queueMicrotask(() => setLoadingPast(true));
    fetch(`/api/conversations/${viewingConversationId}/messages`)
      .then(r => r.json())
      .then(data => {
        const formatted = data.map((m, i) => ({
          id: i + 1,
          role: m.role,
          text: m.body,
          timestamp: m.created_at,
        }));
        setPastMessages(formatted);
      })
      .catch(() => setPastMessages([]))
      .finally(() => setLoadingPast(false));
