  useEffect(() => {
    if (!readAloud) speech.stopSpeaking();
  }, [readAloud, speech]);

  // Dismiss welcome back when user sends their first message
  useEffect(() => {
    if (messages.length > 0 && welcomeBack) {
      const hasUserMsg = messages.some(m => m.role === 'user');
      if (hasUserMsg) dismissWelcomeBack();
    }
