    }
  }, [messages, isTyping]);

  // When read-aloud is on, speak each newly arrived assistant message exactly
  // once. Past-conversation viewing skips this so opening an old chat doesn't
  // start narrating from the top.
  useEffect(() => {
    if (!readAloud || isViewingPast) return;
    if (!speech.synthSupported) return;
    const lastMsg = messages[messages.length - 1];
    if (!lastMsg || lastMsg.role !== 'assistant' || !lastMsg.text) return;
    if (lastSpokenIdRef.current === lastMsg.id) return;
    lastSpokenIdRef.current = lastMsg.id;
    speech.speak(lastMsg.text);
  }, [messages, readAloud, isViewingPast, speech]);

