import { useSpeech } from '../../hooks/useSpeech';
import './ChatWindow.css';

/**
 * Extract artifacts from messages — one artifact per message (not per type).
 * A message with both findings + guide becomes one combined artifact.
 */
function collectArtifacts(messages) {
  const artifacts = [];
  for (const msg of messages) {
    if (msg.role !== 'assistant') continue;
    const hasAny = msg.guide || msg.resources || msg.findings || msg.videos || msg.practice;
    if (!hasAny) continue;

    artifacts.push({
      msgId: msg.id,
      guide: msg.guide || null,
      findings: msg.findings || null,
      resources: msg.resources || null,
      videos: msg.videos || null,
      practice: msg.practice || null,
    });
  }
  return artifacts;
}

function ChatWindow({ userId, userName, readAloud, viewingConversationId, onConversationChange, startNewChatRef }) {
  const {
    messages: liveMessages,
    sendMessage,
    gatherResources,
    pairAgent,
    agentConnected,
    runCommand,
    isConnected,
    isTyping,
    activeSequence,
    welcomeBack,
    dismissWelcomeBack,
    conversationId,
    feedbackPrompt,
    startNewChat,
    endChat,
    submitFeedback,
    skipFeedback,
    terminalHistory,
    terminalCwd,
    sendTerminalCommand,
    sendScreenFrame,
